   144  static int config__add_listener(struct mosquitto__config *config)
   145  {
   146          struct mosquitto__listener *listener;
   147
   148          config->listener_count++;
   149          config->listeners = mosquitto__realloc(config->listeners, sizeof(struct mosquitto__listener)*(size_t)config->listener_count);
   150          if(!config->listeners){
   151                  log__printf(NULL, MOSQ_LOG_ERR, "Error: Out of memory.");
   152                  return MOSQ_ERR_NOMEM;
   153          }
   154          listener = &config->listeners[config->listener_count-1];
   155          memset(listener, 0, sizeof(struct mosquitto__listener));
   156          listener->security_options = mosquitto_calloc(1, sizeof(struct mosquitto__security_options));
   157          if(!listener->security_options){
   158                  log__printf(NULL, MOSQ_LOG_ERR, "Error: Out of memory.");
   159                  return MOSQ_ERR_NOMEM;
   160          }
   161
   162          return MOSQ_ERR_SUCCESS;
   163  }
