   165  static int config__create_default_listener(struct mosquitto__config *config, const char *option_name)
   166  {
   167          if(config->default_listener) return MOSQ_ERR_SUCCESS;
   168          log__printf(NULL, MOSQ_LOG_INFO, "Creating default listener due to '%s' option.", option_name);
   169          log__printf(NULL, MOSQ_LOG_INFO, "It is best practice to define a 'listener' first. Using the '%s' option without a listener will be disabled in the future.", option_name);
   170          if(config__add_listener(config)){
   171                  log__printf(NULL, MOSQ_LOG_ERR, "Error: Out of memory.");
   172                  return MOSQ_ERR_NOMEM;
   173          }
   174
   175          config->default_listener = &config->listeners[config->listener_count-1];
   176          listener__set_defaults(config->default_listener);
   177          config->default_listener->port = 1883;
   178
   179          return MOSQ_ERR_SUCCESS;
   180  }
